<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Support\Str;
class Booking extends Model{protected $fillable=['reference','tour_id','tour_departure_id','pickup_point_id','type','status','first_name','last_name','phone','email','whatsapp','date_of_birth','age','address','participant_count','comments','special_requests','mobility_information','food_allergies','meal_selection','promo_code','source'];protected $casts=['date_of_birth'=>'date','age'=>'integer'];protected static function booted():void{static::creating(fn($m)=>$m->reference??='DT-'.strtoupper(Str::random(8)));}public function tour(){return $this->belongsTo(Tour::class);}public function departure(){return $this->belongsTo(TourDeparture::class,'tour_departure_id');}public function pickupPoint(){return $this->belongsTo(PickupPoint::class);}public function passengers(){return $this->hasMany(BookingPassenger::class);}}
